import {
  analyzePrec,
  clearRelations,
  cycleRelation,
  parseTerminals,
  precTable,
  setRelation,
  setTerminals,
  type Prec,
  type PrecTable,
  type Rel,
} from '#/lib/precedence'
import { hasPrecTable, loadPrecExample } from '#/lib/precOps'
import type { ProjectData } from '#/lib/project'
