type Update = (fn: (d: ProjectData) => ProjectData) => void

const REL_STYLE: Record<Rel, string> = {
  '': '',
  '<': 'bg-sky-500/15 text-sky-300',
  '=': 'bg-emerald-500/15 text-emerald-300',
  '>': 'bg-amber-500/15 text-amber-300',
}

const KEY_REL: Record<string, Rel> = { '<': '<', '=': '=', '>': '>', l: '<', e: '=', g: '>', Backspace: '', Delete: '' }

const cellName = (row: string, col: string, rel: Rel) => `riadok ${row}, stĺpec ${col}: ${rel || 'prázdne'}`

/** Grid position of a cell button (from its data attributes), or null for anything else in the table. */
function cellOf(el: EventTarget): (GridCell & { button: HTMLButtonElement }) | null {
  const button = (el as Element).closest?.<HTMLButtonElement>('button[data-r]')
  if (!button) return null
  return { row: Number(button.dataset.r), col: Number(button.dataset.c), button }
}

// One table row; memoized so moving the roving focus re-renders only the two rows whose tab stop changed.
const GridRow = memo(function GridRow({
  index,
  terminal,
  columns,
  relations,
  activeCol,
}: {
  index: number
  terminal: string
  columns: string[]
  relations: Rel[]
  /** Column of the grid's single tab stop when it is in this row, else -1. */
  activeCol: number
}) {
  return (
    <tr role="row">
      <th scope="row" role="rowheader" className={headCell}>
        {terminal}
      </th>
      {columns.map((c, ci) => {
        const v = relations[ci]
        return (
          <td key={c} role="gridcell" className="border border-white/10 p-0">
            <button
              type="button"
              data-r={index}
              data-c={ci}
              tabIndex={ci === activeCol ? 0 : -1}
              aria-label={cellName(terminal, c, v)}
              className={cx(
                'h-8 w-9 cursor-pointer text-[15px] font-bold transition-colors hover:bg-indigo-400/20 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-indigo-400',
                REL_STYLE[v],
              )}
            >
              {v}
            </button>
          </td>
        )
      })}
    </tr>
  )
})

const PrecGrid = memo(function PrecGrid({
  table,
  labelledBy,
  describedBy,
  setCell,
  cycleCell,
  onDescribe,
}: {
  table: PrecTable
  labelledBy: string
  describedBy: string
  setCell: (a: string, b: string, v: Rel) => void
  cycleCell: (a: string, b: string) => void
  onDescribe: (text: string) => void
}) {
  const { columns: cols, rows } = table
  const size = { rows: rows.length, cols: cols.length }
  const [active, setActive] = useState<GridCell>({ row: 0, col: 0 })
  // Terminals may have been removed since the active cell was remembered.
  const at = clampCell(active, size)
  const tableRef = useRef<HTMLTableElement>(null)

  const describe = (cell: GridCell) => {
    const a = cols[cell.row]
    const b = cols[cell.col]
    onDescribe(`Tabuľka[${a}, ${b}] = ${rows[cell.row].relations[cell.col] || 'prázdne (chyba)'}`)
  }

  const onKeyDown = (e: KeyboardEvent<HTMLTableElement>) => {
    const cell = cellOf(e.target)
    if (!cell || e.defaultPrevented) return
    const plain = !e.ctrlKey && !e.metaKey && !e.altKey
    if (plain && e.key in KEY_REL) {
      e.preventDefault()
      setCell(cols[cell.row], cols[cell.col], KEY_REL[e.key])
      return
    }
    // Only a key with a target cell is taken over; at an edge the browser keeps its native scrolling.
    const to = gridMove(e, cell, size)
    if (!to) return
    e.preventDefault()
    const next = tableRef.current?.querySelector<HTMLButtonElement>(`button[data-r="${to.row}"][data-c="${to.col}"]`)
    next?.focus()
    next?.scrollIntoView({ block: 'nearest', inline: 'nearest' })
  }

  const onClick = (e: MouseEvent<HTMLTableElement>) => {
    const cell = cellOf(e.target)
    if (cell) cycleCell(cols[cell.row], cols[cell.col])
  }

  const onContextMenu = (e: MouseEvent<HTMLTableElement>) => {
    const cell = cellOf(e.target)
    if (!cell) return
    e.preventDefault()
    setCell(cols[cell.row], cols[cell.col], '')
  }

  const onFocus = (e: FocusEvent<HTMLTableElement>) => {
    const cell = cellOf(e.target)
    if (!cell) return
    setActive({ row: cell.row, col: cell.col })
    describe(cell)
  }

  const onMouseOver = (e: MouseEvent<HTMLTableElement>) => {
    const cell = cellOf(e.target)
    if (cell) describe(cell)
  }

  return (
    <div className="overflow-x-auto pb-1">
      <table
        ref={tableRef}
        role="grid"
        aria-labelledby={labelledBy}
        aria-describedby={describedBy}
        className="border-collapse font-mono text-[13px]"
        onKeyDown={onKeyDown}
        onClick={onClick}
        onContextMenu={onContextMenu}
        onFocus={onFocus}
        onMouseOver={onMouseOver}
        onMouseLeave={() => onDescribe('')}
      >
        <thead>
          <tr role="row">
            <th scope="col" role="columnheader" className={cx(headCell, 'text-[10px] leading-tight font-normal text-zinc-400')}>
              zásobník ↓
              <br />
              vstup →
            </th>
            {cols.map((c) => (
              <th key={c} scope="col" role="columnheader" className={headCell}>
                {c}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map(({ terminal, relations }, ri) => (
            <GridRow key={terminal} index={ri} terminal={terminal} columns={cols} relations={relations} activeCol={ri === at.row ? at.col : -1} />
          ))}
        </tbody>
      </table>
    </div>
  )
})

/** The relation grid plus its hover/focus detail line; the line's state lives here so it never re-renders the grid. */
function PrecGridSection(props: Omit<Parameters<typeof PrecGrid>[0], 'onDescribe'>) {
  const [detail, setDetail] = useState('')
  return (
    <>
      <PrecGrid {...props} onDescribe={setDetail} />
      <div className="mt-2 h-5 font-mono text-xs text-zinc-400">{detail}</div>
    </>
  )
}

export function PrecTab({ data, update }: { data: ProjectData; update: Update }) {
  const prec = data.prec
  const confirm = useConfirm()
  const setPrec = useCallback((fn: (p: Prec) => Prec) => update((d) => ({ ...d, prec: fn(d.prec) })), [update])
  const setCell = useCallback((a: string, b: string, v: Rel) => setPrec((p) => setRelation(p, a, b, v)), [setPrec])
  const cycleCell = useCallback((a: string, b: string) => setPrec((p) => cycleRelation(p, a, b)), [setPrec])
  const [termsDraft, setTermsDraft] = useState(prec.terminals.join(' '))
  // precTable reads only terminals and cells; typing rules or simulation input keeps both, so the grid is not rebuilt.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const table = useMemo(() => precTable(prec), [prec.terminals, prec.cells])
  // Checks and simulation may lag behind typing; the grid and fields stay immediate.
  const deferredPrec = useDeferredValue(prec)
  const { problems, simulation: sim } = useMemo(() => analyzePrec(deferredPrec), [deferredPrec])
  const hasTable = prec.terminals.length > 0

  const ids = {
    terms: useId(),
    termsHelp: useId(),
    termsHeading: useId(),
    rules: useId(),
    rulesHelp: useId(),
    input: useId(),
    inputHelp: useId(),
    gridHeading: useId(),
    gridHelp: useId(),
  }

  const termsKey = prec.terminals.join(' ')
  useEffect(() => setTermsDraft(termsKey), [termsKey])

  // A form: Enter submits natively, and browsers do not submit on the Enter that confirms an IME composition.
  const applyTerms = (e: FormEvent) => {
    e.preventDefault()
    setPrec((p) => setTerminals(p, parseTerminals(termsDraft)))
  }

  const clearCells = async () => {
    if (!Object.keys(prec.cells).length) return
    const ok = await confirm({
      title: 'Vyčistiť bunky tabuľky?',
      body: 'Všetky relácie v precedenčnej tabuľke sa vymažú. Terminály, pravidlá a vstup simulácie zostanú.',
      confirmLabel: 'Vyčistiť bunky',
      tone: 'danger',
    })
    if (ok) setPrec(clearRelations)
  }

  const loadExample = async () => {
    if (
      hasPrecTable(data) &&
      !(await confirm({
        title: 'Načítať príklad G_expr2?',
        body: 'Terminály, tabuľka, pravidlá a vstup simulácie sa nahradia príkladom.',
        confirmLabel: 'Nahradiť príkladom',
        tone: 'danger',
      }))
    )
      return
    update(loadPrecExample)
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Make the two sections left and right resizable"
  // Changes: Resizable two-column layout.
  return (
    <SplitLayout>
      <div className="min-w-0">
        <Panel title={<span id={ids.termsHeading}>Terminály tabuľky</span>}>
          <form onSubmit={applyTerms} aria-labelledby={ids.termsHeading}>
            <Label htmlFor={ids.terms}>Terminály v poradí riadkov a stĺpcov</Label>
            <TextInput
              id={ids.terms}
              value={termsDraft}
              placeholder="+ * ( ) i"
              enterKeyHint="done"
              autoComplete="off"
              aria-describedby={ids.termsHelp}
              onChange={(e) => setTermsDraft(e.target.value)}
            />
            <Help>
              <span id={ids.termsHelp}>
                Oddelené medzerou, v poradí riadkov/stĺpcov. <code>$</code> sa pridá automaticky na koniec. Bunky existujúcich
                terminálov sa zachovajú.
              </span>
            </Help>
            <div className="mt-3 flex flex-wrap gap-2">
              <PrimaryButton type="submit">Použiť</PrimaryButton>
              <DangerButton onClick={clearCells}>Vyčistiť bunky</DangerButton>
            </div>
          </form>
        </Panel>

        <Panel title="Redukčné pravidlá">
          <Label htmlFor={ids.rules}>Pravidlá, jedno na riadok</Label>
          <TextArea
            id={ids.rules}
            rows={8}
            wrap="off"
            value={prec.rules}
            placeholder={'E -> E + E\nE -> E * E\nE -> ( E )\nE -> i'}
            aria-describedby={ids.rulesHelp}
            onChange={(e) => setPrec((p) => ({ ...p, rules: e.target.value }))}
          />
          <Help>
            <span id={ids.rulesHelp}>
              Rovnaký formát ako pri LL. Použijú sa na kontrolu a pri simulácii (redukcia <code>&lt;y → A</code>).
            </span>
          </Help>
          <div className="mt-3">
            <Button onClick={loadExample}>
              Príklad G<sub>expr2</sub>
            </Button>
          </div>
        </Panel>

        <Panel title="Simulácia precedenčnej analýzy">
          <Label htmlFor={ids.input}>Vstupné tokeny</Label>
          <TextInput
            id={ids.input}
            value={prec.input}
            placeholder="i + i * i"
            autoComplete="off"
            aria-describedby={ids.inputHelp}
            onChange={(e) => setPrec((p) => ({ ...p, input: e.target.value }))}
          />
          <Help>
            <span id={ids.inputHelp}>
              Tokeny oddelené medzerou, <code>$</code> sa pridá automaticky.
            </span>
          </Help>
          {sim && (
            <>
              <div className="mt-3">
                <ListTable head={['Krok', 'Zásobník', 'Op', 'Vstup', 'Pravidlo']} caption="Priebeh precedenčnej analýzy">
                  {sim.rows.map((r, i) => (
                    <tr key={i}>
                      <RowHeader className="text-zinc-400 tabular-nums">{i + 1}</RowHeader>
                      <td>
                        {r.stack.map((it, j) => (
                          <span key={j} className={it.kind === 'm' ? 'font-bold text-sky-300' : it.kind === 'n' ? 'text-indigo-200' : ''}>
                            {j > 0 && ' '}
                            {it.s}
                          </span>
                        ))}
                      </td>
                      <td className="text-center font-bold">{r.op}</td>
                      <td>{r.input}</td>
                      <td className="text-zinc-400">{r.rule}</td>
                    </tr>
                  ))}
                </ListTable>
              </div>
              <ResultLine ok={sim.ok}>{sim.ok ? sim.message : `Chyba: ${sim.message}`}</ResultLine>
            </>
          )}
        </Panel>
      </div>

      <div className="min-w-0">
        <Panel title="Kontrola">
          <Problems items={problems} />
        </Panel>
        <Panel title={<span id={ids.gridHeading}>Precedenčná tabuľka</span>}>
          <Help>
            <span id={ids.gridHelp}>
              Riadok = terminál najbližšie vrcholu zásobníka, stĺpec = vstupný token. Klik prepína <code>&lt;</code> →{' '}
              <code>=</code> → <code>&gt;</code> → prázdne, pravý klik maže. Na označenej bunke: klávesy <code>&lt;</code>{' '}
              <code>=</code> <code>&gt;</code> (alebo <code>l</code> <code>e</code> <code>g</code>), <code>Backspace</code>,
              šípky, <code>Home</code>/<code>End</code> (s <code>Ctrl</code> na začiatok/koniec tabuľky).
            </span>
          </Help>
          {hasTable && (
            <div className="mt-3">
              <PrecGridSection table={table} labelledBy={ids.gridHeading} describedBy={ids.gridHelp} setCell={setCell} cycleCell={cycleCell} />
            </div>
          )}
        </Panel>
      </div>
    </SplitLayout>
  )
}
